@@ -0,0 +1,34 @@
+name: Cinder C01 playtest
+on:
+  push:
+    branches: [codex/cinder-shift-c01-playtest]
+concurrency:
+  group: cinder-c01-playtest
+  cancel-in-progress: true
+permissions:
+  contents: read
+jobs:
+  compare:
+    runs-on: ubuntu-latest
+    timeout-minutes: 12
+    steps:
+      - uses: actions/checkout@v4
+      - uses: actions/setup-node@v4
+        with:
+          node-version: 22
+          cache: npm
+      - run: npm ci --ignore-scripts
+      - run: npx playwright install --with-deps chromium
+      - run: npm run check
+      - run: node scripts/build-c01-playtest.mjs
+      - name: Verify ordinary A/B routes, saves, turret and experiment boundary
+        run: npx playwright test --config=playwright.c01.config.ts --reporter=line,json
+        env:
+          PLAYWRIGHT_JSON_OUTPUT_FILE: test-results/c01-playtest.json
+      - uses: actions/upload-artifact@v4
+        if: always()
+        with:
+          name: cinder-c01-playtest-${{ github.run_number }}
+          path: |
+            dist/c01-playtest
+            test-results
